"""Create an HTML layout preview of the Unity menu. Not a Unity capture."""
from pathlib import Path
import html
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'Documentation/CinematicMenuPreview.html'
ASSET='../Assets/Game/Resources/BlackstoneFoundation/Menu/'
nav=[('play','Resume game'),('book','Chapter 01'),('map','Island locations'),('settings','Settings'),('controls','Controls'),('exit','Return to title')]
features=[('cell','Cellhouse &<br>galleries'),('boat','Coastal<br>patrol boat'),('helicopter','Helicopter<br>flight'),('boxing','Boxing<br>training'),('cards','Texas<br>Hold’em')]
buttons=''.join(f'<div class="nav {"selected" if i==0 else ""}" style="top:{344+i*82}px"><img src="{ASSET}{icon}.png"><span class="number">{i+1:02}</span><span class="label">{html.escape(label)}</span><span class="arrow">›</span></div>' for i,(icon,label) in enumerate(nav))
cards=''.join(f'<div class="feature" style="left:{665+i*170}px"><img src="{ASSET}{icon}.png"><div>{label}</div></div>' for i,(icon,label) in enumerate(features))
OUT.write_text('''<!doctype html><meta charset="utf-8"><title>Cinematic menu — offline layout preview</title><style>
@font-face{font-family:Anton;src:url('''+ASSET+'''Heading.ttf)}*{box-sizing:border-box}body{margin:0;background:#000;color:#ede8d9;font-family:Arial,sans-serif}.canvas{position:absolute;width:1920px;height:1080px;transform-origin:top left;background:url('''+ASSET+'''Background.png) center/cover}.sidebar{position:absolute;inset:0 auto 0 0;width:590px;background:rgba(4,5,6,.82);border-right:2px solid #d4ad6360}.shade{position:absolute;inset:0 0 0 590px;background:rgba(3,5,6,.3)}.caption{position:absolute;color:#d4ad63;font-size:16px;letter-spacing:2px}.rule{position:absolute;height:1px;background:#d4ad63}.title{position:absolute;left:94px;top:110px;height:165px;line-height:165px;font-family:Anton;font-size:124px}.nav{position:absolute;left:95px;width:460px;height:72px;background:#091015e6;border:1px solid #88888059;display:flex;align-items:center}.nav.selected{background:#473013d4;border:2px solid #d4ad63;box-shadow:0 0 12px #e4aa5270}.nav img{position:absolute;left:25px;width:34px;height:34px}.number{position:absolute;left:91px;color:#d4ad63;font-size:22px}.label{position:absolute;left:149px;font-size:24px}.arrow{position:absolute;right:12px;font-size:30px;color:#d4ad63}.hero{position:absolute;left:665px;top:285px;width:1170px;font-family:Anton;font-size:76px;line-height:105px}.body{position:absolute;left:665px;top:464px;width:650px;font-size:24px;line-height:36px}.feature{position:absolute;top:745px;width:170px;height:146px;border-right:1px solid #d4ad6373;padding-left:8px}.feature:last-child{border:0}.feature img{width:56px;height:48px;object-fit:contain}.feature div{margin-top:14px;font-size:24px;line-height:30px}.notice{position:absolute;right:18px;bottom:10px;color:#ded5c1;font-size:12px;background:#0009;padding:5px}
</style><div class="canvas"><div class="sidebar"></div><div class="shade"></div>
<div class="caption" style="left:100px;top:54px">THE SILENT BLUEPRINT</div><div class="rule" style="left:100px;top:91px;width:450px"></div><div class="title">PAUSED</div><div class="caption" style="left:100px;top:274px">SESSION PAUSED / CELLHOUSE</div><div class="rule" style="left:100px;top:313px;width:450px;opacity:.65"></div>'''+buttons+'''
<div class="caption" style="right:55px;top:54px">ALCATRAZ / CHAPTER 01</div><div class="caption" style="left:665px;top:260px">CHAPTER 01 / THE PRISONER</div><div class="hero">A WAY OUT BEGINS HERE.</div><div class="rule" style="left:665px;top:421px;width:80px;height:3px"></div><div class="body">Discover the island, meet the inmates and learn the prison routine. Build alliances. Find your route to freedom.</div><div class="rule" style="left:665px;top:655px;width:1170px;opacity:.5"></div><div class="caption" style="left:665px;top:685px">AVAILABLE ON THE ISLAND</div>'''+cards+'''
<div class="caption" style="left:100px;top:998px">ELIAS VALE · INMATE B-04</div><div class="rule" style="left:100px;top:1027px;width:450px"></div><div class="notice">OFFLINE LAYOUT PREVIEW — NOT UNITY GAMEPLAY</div></div><script>function fit(){let s=Math.min(innerWidth/1920,innerHeight/1080),c=document.querySelector('.canvas');c.style.transform='scale('+s+')';c.style.left=(innerWidth-1920*s)/2+'px';c.style.top=(innerHeight-1080*s)/2+'px'}onresize=fit;fit()</script>''')
print(OUT)
